}

const EMPTY_TRIGGER_SOURCES: ActionScheduleTriggerSources = { accountTrackers: [], cards: [], targetStates: [] }
const EMPTY_SOURCES: CardSequenceValidationSources = {
    actionIds: [],
    cardsAvailable: true,
    readyStates: [],
