    // The caller resolves the project config and starts the action runner; the scheduler's only
    // project-derived input is the actions folder holding its own schedules file.
    async startProject(project, paths, projectConfig) {
        if (!paths || typeof paths.actionsFolder !== 'string' || paths.actionsFolder.length === 0) {
            throw new Error('Missing scheduler actionsFolder');
        }
        if (typeof paths.activeCardsFolder !== 'string' || paths.activeCardsFolder.length === 0) {
            throw new Error('Missing scheduler activeCardsFolder');
        }
        if (!Array.isArray(projectConfig?.states)) throw new Error('Missing scheduler project states');
        if (!Array.isArray(projectConfig.cardTypes)) throw new Error('Missing scheduler project card types');
        this.clearProjectState();
        this.project = requireProject(project);
        this.actionsFolder = paths.actionsFolder;
        this.activeCardsFolder = paths.activeCardsFolder;
        this.projectFolder = paths.projectFolder;
        this.cardTypes = projectConfig.cardTypes;
        this.configuredStates = projectConfig.states.map(({ state }) => state);
        const generation = this.projectGeneration;
        const executionContext = {
            actionsFolder: this.actionsFolder,
            activeCardsFolder: this.activeCardsFolder,
            cardTypes: this.cardTypes,
            generation,
            project: this.project,
            projectFolder: this.projectFolder,
        };
        const worktreeExecution = new SequenceWorktreeExecution({
            project: this.project,
            projectFolder: paths.projectFolder,
            activeCardsFolder: this.activeCardsFolder,
            worktreeService: this.worktreeService,
            localGitService: this.localGitService,
            saveSequence: (sequence) => this.saveSequence(sequence, executionContext),
            onStateChange: (cardInternalId, state, checkoutPath) => (
                this.handleSequenceCheckoutState(cardInternalId, state, checkoutPath, generation)
            ),
            onError: (scheduleId, error) => this.sequenceEngine.failExternal(scheduleId, error),
            isCancelled: (scheduleId) => (
                generation !== this.projectGeneration || this.sequenceEngine.cancelledSchedules.has(scheduleId)
            ),
        });
        this.sequenceEngine = new ScheduledCardSequenceEngine({
            worktreeExecution,
            reportError: (error) => this.reportError(error),
            actionRunnerService: this.actionRunnerService,
            allocateConversationId,
            allocateRunId: allocateActionRunId,
            conversationResumeFailure: (cardInternalId, conversationId) => (
                this.conversationResumeFailure(cardInternalId, conversationId, executionContext)
            ),
            isCurrent: () => generation === this.projectGeneration,
            loadSchedules: () => this.loadSchedules(executionContext),
            resolveCardContext: (cardInternalId, sequence) => this.resolveSequenceCardContext(cardInternalId, sequence, executionContext),
            resolvePrimaryCardContext: (cardInternalId) => this.resolveCardContext(cardInternalId, executionContext),
            saveSequence: (sequence) => this.saveSequence(sequence, executionContext),
            states: this.configuredStates,
        });
        await this.reconcile({ startup: true });
    }

    stop() {
        this.clearProjectState();
        for (const unsubscribe of this.accountUsageUnsubscribers) unsubscribe();
        this.accountUsageUnsubscribers = [];

import { findCatalogModel, type AgentModelCatalog } from './agent_model_catalog';

export interface AgentModelOption {
    description?: string;
    displayName: string;
    id: string;
}

/** Keep saved identifiers visible without substituting provider aliases or defaults. */
export function agentModelOptions(catalog: AgentModelCatalog | null, selectedModel: string): AgentModelOption[] {
    const options = catalog?.models.filter(({ hidden, id }) => !hidden || id === selectedModel)
        .map(({ id, displayName, description }) => ({ description, displayName, id })) ?? [];
    if (!selectedModel || options.some(({ id }) => id === selectedModel)) return options;
    const advertisedModel = catalog ? findCatalogModel(catalog, selectedModel) : null;

    return [{
        description: advertisedModel?.description,
        displayName: advertisedModel?.displayName ?? selectedModel,
        id: selectedModel,
    }, ...options];
}

        },
    }
}

export function selectPermissionMode(selection, permissionMode) {
    return { ...selection, permissionMode: validatePermissionMode(permissionMode, 'agent selection') }
}

export function projectAgentSelection(selection, profiles = []) {
    const settings = selection.settingsByAgent[selection.activeAgent]
    if (!settings) throw new Error(`Missing settings for active agent: ${selection.activeAgent}`)
    const profile = findAgentProfile(profiles, selection.activeAgent)

    return {
        agent: selection.activeAgent,
        model: settings.model,
        ...(profile && supportsPermissionMode(profile) ? { permissionMode: selection.permissionMode } : {}),
        thinkingLevel: settings.thinkingLevel,
        ...(settings.speedMode !== undefined ? { speedMode: settings.speedMode } : {}),
    }
}
